 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, Color, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'journal-quote-panel';

  const body = new Group();
  root.add(body);

  const colors = config.colors || config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkC = new Color(colors.ink);
  const surfaceC = new Color(colors.surface);
  const paperC = new Color(colors.paper);
  const accentC = new Color(colors.accent);

  const activeTimelines = [];
  const cleanupFns = [];
  let loadedTexture = null;
  let isDestroyed = false;

  // --- gradient stage backdrop ---
  const bgGeo = new PlaneGeometry(3.4, 2.2);
  const uSurface = uniform(surfaceC);
  const uInk = uniform(inkC);
  const uvNode = uv();
  const gradientNode = mix(uSurface, uInk, smoothstep(0.0, 1.0, uvNode.y));
  const bgMat = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    transparent: true,
    opacity: 0.96,
    side: DoubleSide,
  });
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -0.22;
  body.add(bg);

  // --- card sizing from atlas rect aspect ---
  const srcW = 512;
  const srcH = 320;
  const cardAspect = srcW / srcH;
  const cardH = 1.5;
  const cardW = cardH * cardAspect;

  // --- accent edge frame ---
  const edgeGeo = new PlaneGeometry(cardW * 1.05, cardH * 1.05);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accentC,
    transparent: true,
    opacity: 0.0,
    side: DoubleSide,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.1;
  body.add(edge);

  // --- textured card ---
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({
    color: paperC,
    side: DoubleSide,
  });
  const card = new Mesh(cardGeo, cardMat);
  card.name = 'quote-image';
  body.add(card);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (isDestroyed) {
        tex.dispose();
        return;
      }
      tex.colorSpace = SRGBColorSpace;
      tex.needsUpdate = true;
      loadedTexture = tex;
      const texMat = new MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        side: DoubleSide,
      });
      card.material = texMat;
      texMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- cinematic primitives ---
  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    if (ctx.primitives?.[p.name]) {
      const instance = ctx.primitives[p.name](root, { ...(p.params || {}), trigger: p.trigger });
      if (instance?.cleanup) cleanupFns.push(instance.cleanup);
      if (instance?.timeline) activeTimelines.push(instance.timeline);
    }
  }

  // --- load entrance ---
  const entrance = gsap.timeline();
  body.scale.set(0.96, 0.96, 0.96);
  body.position.y = -0.08;
  entrance.to(body.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  entrance.to(body.scale, { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power4.out' }, 0);
  activeTimelines.push(entrance);

  // --- interaction handlers ---
  function setHover(active) {
    gsap.to(body.position, {
      z: active ? 0.15 : 0,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto',
    });
    gsap.to(edgeMat, {
      opacity: active ? 0.65 : 0,
      duration: 0.25,
      overwrite: 'auto',
    });
  }

  root.userData.handlers = {
    hover: (evt) => {
      const active = evt === true || evt?.active === true || evt?.type === 'enter';
      setHover(active);
    },
    focus: (evt) => {
      setHover(evt === true || evt?.active === true);
    },
    click: () => {
      gsap.to(body.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('hub-journal.select', { nodeId: config.id });
    },
  };

  root.userData.cleanup = () => {
    isDestroyed = true;
    activeTimelines.forEach((t) => { try { t.kill(); } catch (e) {} });
    gsap.killTweensOf([root, body, edgeMat, cardMat]);
    cleanupFns.forEach((fn) => { try { fn(); } catch (e) {} });
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
    if (loadedTexture) loadedTexture.dispose();
  };

  return root;
}
